/**
 * Small 2D affine helpers for the web-native backend.
 *
 * The native animation path needs to answer one question for every animated
 * mobject: *is the motion between the start and the end state a rigid/scaling
 * affine* (translate, scale, rotate, shear) or a genuine shape morph?  An
 * affine motion can be handed to the browser as a CSS `transform`; a morph has
 * to become a crossfade (see the animation mapping).  The answer comes from a
 * least-squares fit of the start points onto the end points, which needs no
 * stored geometry: both point arrays exist for the duration of the fit only.
 */
/**
 * A world-space affine map: `p' = M p + t`, with `M` stored row-major as
 * `[a, c, b, d]` so that `x' = a x + c y + t.x` and `y' = b x + d y + t.y`.
 */
export interface Affine2D {
    a: number;
    b: number;
    c: number;
    d: number;
    tx: number;
    ty: number;
}
export declare const IDENTITY: Affine2D;
export interface AffineFit {
    /** Best-fit affine, or {@link IDENTITY} when there is not enough data. */
    matrix: Affine2D;
    /**
     * True when the normal equations were rank-deficient (too few points, or all
     * points collinear).  The residual is meaningless then and must not be used
     * to decide that two shapes are unrelated.
     */
    degenerate: boolean;
    /**
     * Root-mean-square residual of the fit relative to the extent of the target
     * shape.  Near zero means "the two shapes are affinely related"; a morph
     * gives a residual of order 1.
     */
    residual: number;
}
/**
 * Fit `end ≈ M · start + t` in the least-squares sense.
 *
 * Solves the two independent 3x3 normal equations (one per output channel) with
 * a small Gaussian elimination; no numpy round-trip, and the whole thing runs in
 * O(n) over the point arrays.
 */
export declare function fitAffine(from: readonly number[][], to: readonly number[][]): AffineFit;
/**
 * Convert a world-space affine into an SVG `matrix(...)` string for an element
 * whose local coordinates are the *world-frame* vectors of the start state.
 *
 * SVG renders in a y-down viewBox while manim is y-up, so the world map is
 * conjugated by `F = diag(1, -1)`: `S = F · (M p + t) · F`.
 */
export declare function affineToSvgMatrix(matrix: Affine2D, centerX: number, centerY: number): string;
